@pytest.mark.parametrize(
    "value",
    ["short", "exactlyten"],
    ids=["shorter than length", "equal to length"],
)
def test_truncated_to_returns_value_when_within_length(value):
    assert truncated_to(10, value) == value


def test_truncated_to_truncates_long_values():
    value = "a" * 100
    result = truncated_to(10, value)

    assert result == "aaaaa...90 additional characters...aaaaa"
    # the truncated form must be shorter than the original
    assert len(result) < len(value)
    # and it should retain the head and tail of the original value
    assert result.startswith(value[:5])
    assert result.endswith(value[-5:])


def test_truncated_to_returns_value_when_marker_is_not_shorter():
    # short-but-over-length strings would grow if the "omitted" marker were
    # inserted, so the original value is returned unchanged instead
    value = "abcdefghijkl"
    assert truncated_to(6, value) == value
